const endpoint='https://graphql.anilist.co';
const jikanEndpoint='https://api.jikan.moe/v4';
const grid=document.querySelector('#animeGrid');
const loading=document.querySelector('#loading');
const title=document.querySelector('#resultsTitle');
const subtitle=document.querySelector('#resultsSubtitle');
const dialog=document.querySelector('#animeDialog');
const dialogContent=document.querySelector('#dialogContent');
const moreButton=document.querySelector('#loadMore');
const favoritesKey='sempai-anime-favorites';const perPage=24;
let currentPage=1,activeGenre=null,activeSearch='',currentItems=[];
let browseMode='season',seasonalItems=[],seasonalCursor=0;

const browseQuery=`query($page:Int,$search:String,$genre:String){Page(page:$page,perPage:${perPage}){pageInfo{hasNextPage}media(type:ANIME,isAdult:false,search:$search,genre:$genre,sort:TRENDING_DESC){id title{romaji english native}coverImage{large}averageScore episodes format status seasonYear genres description(asHtml:false)}}}`;
const seasonalQuery=`query($season:MediaSeason!,$seasonYear:Int!){Page(page:1,perPage:50){media(type:ANIME,isAdult:false,status:RELEASING,season:$season,seasonYear:$seasonYear,sort:TRENDING_DESC){id title{romaji english native}coverImage{large}averageScore episodes format status seasonYear genres description(asHtml:false)}}}`;
const heroQuery=`query{gojo:Character(search:"Satoru Gojo"){name{full}image{large}}naruto:Character(search:"Naruto Uzumaki"){name{full}image{large}}luffy:Character(search:"Monkey D. Luffy"){name{full}image{large}}tanjiro:Character(search:"Tanjirou Kamado"){name{full}image{large}}}`;

const favorites=()=>JSON.parse(localStorage.getItem(favoritesKey)||'[]');
const setFavorites=value=>{localStorage.setItem(favoritesKey,JSON.stringify(value));updateFavoriteCount()};
const updateFavoriteCount=()=>document.querySelector('#favoriteCount').textContent=favorites().length;
const animeTitle=anime=>anime.title.english||anime.title.romaji||anime.title.native;
const escapeHtml=(value='')=>{const node=document.createElement('div');node.textContent=value;return node.innerHTML};let toastTimer;const toast=message=>{const box=document.querySelector('#toast');if(!box)return;clearTimeout(toastTimer);box.textContent=message;box.classList.remove('show');requestAnimationFrame(()=>box.classList.add('show'));toastTimer=setTimeout(()=>{box.classList.remove('show');box.textContent=''},3200)};
const setLoading=value=>loading.hidden=!value;

function currentSeason(){const now=new Date(),month=now.getMonth()+1;let season='WINTER',year=now.getFullYear();if(month>=3&&month<=5)season='SPRING';else if(month>=6&&month<=8)season='SUMMER';else if(month>=9&&month<=11)season='FALL';else if(month===12)year++;const labels={WINTER:'hiver',SPRING:'printemps',SUMMER:'été',FALL:'automne'};return{season,year,label:labels[season]}}
function shuffle(items){const copy=[...items];for(let index=copy.length-1;index>0;index--){const other=Math.floor(Math.random()*(index+1));[copy[index],copy[other]]=[copy[other],copy[index]]}return copy}
function renderCards(items,{append=false}={}){if(!items.length&&!append){grid.innerHTML='<div class="empty">Aucun anime trouvé. Essaie une autre humeur ou reviens dans quelques instants.</div>';return}const html=items.map(anime=>`<article class="anime-card" data-id="${anime.id}" tabindex="0"><div class="cover">${anime.coverImage?.large?`<img src="${anime.coverImage.large}" alt="Affiche de ${escapeHtml(animeTitle(anime))}" loading="lazy">`:''}<span class="score">★ ${anime.averageScore?Math.round(anime.averageScore/10)+'/10':'—'}</span></div><div class="card-info"><h3>${escapeHtml(animeTitle(anime))}</h3><p>${anime.format||'Anime'} · ${anime.episodes||'?'} ép.</p></div></article>`).join('');if(append)grid.insertAdjacentHTML('beforeend',html);else grid.innerHTML=html}
function showSeasonBatch(){const batch=seasonalItems.slice(seasonalCursor,seasonalCursor+perPage);currentItems=batch;renderCards(batch);moreButton.hidden=seasonalItems.length<=perPage;moreButton.textContent='Voir une autre sélection';const info=currentSeason();title.textContent=`Les sorties de l’${info.label} ${info.year}`;subtitle.textContent=`${seasonalItems.length} anime en cours repérés cette saison. La sélection change à chaque visite.`}
function nextSeasonBatch(){if(!seasonalItems.length)return;if(seasonalCursor+perPage>=seasonalItems.length){seasonalItems=shuffle(seasonalItems);seasonalCursor=0}else seasonalCursor+=perPage;showSeasonBatch();grid.scrollIntoView({behavior:'smooth',block:'start'})}
async function loadSeasonalAnime(){setLoading(true);grid.innerHTML='';try{const info=currentSeason();const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({query:seasonalQuery,variables:{season:info.season,seasonYear:info.year}})});const payload=await response.json();if(payload.errors)throw Error(payload.errors[0].message);seasonalItems=shuffle(payload.data?.Page?.media||[]);seasonalCursor=0;browseMode='season';showSeasonBatch()}catch(error){browseMode='explore';title.textContent='En tendance maintenant';subtitle.textContent='La saison est momentanément indisponible : voici les tendances.';await loadAnime()}finally{setLoading(false)}}
async function loadAnime({append=false}={}){setLoading(true);if(!append)grid.innerHTML='';try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({query:browseQuery,variables:{page:currentPage,search:activeSearch||null,genre:activeGenre}})});const payload=await response.json();if(payload.errors)throw Error(payload.errors[0].message);const page=payload.data.Page;if(!append&&activeSearch&&!page.media.length){await loadJikan({fallback:true});return}currentItems=append?[...currentItems,...page.media]:page.media;renderCards(append?page.media:currentItems,{append});moreButton.hidden=!page.pageInfo.hasNextPage;moreButton.textContent='Voir plus'}catch(error){if(!append)await loadJikan({fallback:true});else toast('La page suivante n’a pas pu être chargée.')}finally{setLoading(false)}}
function normalizeJikan(anime){return{id:anime.mal_id,title:{romaji:anime.title,english:anime.title_english,native:anime.title_japanese},coverImage:{large:anime.images?.jpg?.large_image_url},averageScore:anime.score?Math.round(anime.score*10):null,episodes:anime.episodes,format:anime.type,status:anime.status,seasonYear:anime.year,genres:(anime.genres||[]).map(genre=>genre.name),description:anime.synopsis}}
async function loadJikan({fallback=false}={}){setLoading(true);grid.innerHTML='';try{const url=activeSearch?`${jikanEndpoint}/anime?q=${encodeURIComponent(activeSearch)}&limit=${perPage}&sfw`:`${jikanEndpoint}/top/anime?limit=${perPage}&sfw`;const response=await fetch(url);if(!response.ok)throw Error();const payload=await response.json();currentItems=(payload.data||[]).map(normalizeJikan);currentPage=1;renderCards(currentItems);moreButton.hidden=true;subtitle.textContent=fallback?(activeSearch?'Recherche élargie via MyAnimeList : essaie aussi le titre anglais, romaji ou japonais.':'AniList est momentanément indisponible : voici les données MyAnimeList via Jikan.'):'Les incontournables MyAnimeList, via Jikan.'}catch(error){grid.innerHTML='<div class="empty">Impossible de joindre AniList ou Jikan pour le moment. Réessaie dans quelques instants.</div>'}finally{setLoading(false)}}
function openAnime(id){const anime=currentItems.find(item=>item.id===Number(id));if(!anime)return;const saved=favorites().includes(anime.id);dialogContent.innerHTML=`<div class="detail"><img class="detail-cover" src="${anime.coverImage?.large||''}" alt=""><div><p class="eyebrow">${escapeHtml(anime.format||'Anime')} ${anime.seasonYear?'· '+anime.seasonYear:''}</p><h2>${escapeHtml(animeTitle(anime))}</h2><p class="meta">★ ${anime.averageScore?Math.round(anime.averageScore/10)+'/10':'Pas encore noté'} · ${anime.episodes||'Nombre d’épisodes inconnu'} épisodes · ${escapeHtml(anime.status||'')}</p><div class="tags">${(anime.genres||[]).map(genre=>`<span>${escapeHtml(genre)}</span>`).join('')}</div><p class="description">${escapeHtml((anime.description||'Description indisponible.').replace(/\n/g,' '))}</p><button class="fav-detail" data-favorite="${anime.id}">${saved?'♥ Retirer de ma liste':'♡ Ajouter à ma liste'}</button></div></div>`;dialog.showModal()}
function toggleFavorite(id){const items=favorites(),index=items.indexOf(Number(id));if(index===-1){items.push(Number(id));toast('Ajouté à ta liste !')}else{items.splice(index,1);toast('Retiré de ta liste.')}setFavorites(items);dialog.close()}
function startSearch(){activeSearch=document.querySelector('#searchInput').value.trim();if(!activeSearch){toast('Écris le titre d’un anime.');return}browseMode='explore';activeGenre=null;document.querySelectorAll('#moodGrid button').forEach(button=>button.classList.remove('active'));currentPage=1;title.textContent=`Résultats pour « ${activeSearch} »`;subtitle.textContent='Découvre les anime correspondants.';loadAnime();document.querySelector('#tendance').scrollIntoView({behavior:'smooth',block:'start'})}
async function loadHeroCharacters(){const target=document.querySelector('#heroCharacters');if(!target)return;try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({query:heroQuery})});const payload=await response.json();const characters=Object.values(payload.data||{}).filter(character=>character?.image?.large);target.innerHTML=characters.map(character=>`<figure class="hero-character"><img src="${character.image.large}" alt="" loading="lazy"><span>${escapeHtml(character.name.full)}</span></figure>`).join('')}catch(error){/* L'interface conserve son décor abstrait si AniList ne répond pas. */}}

document.querySelector('#moodGrid').addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;browseMode='explore';document.querySelectorAll('#moodGrid button').forEach(item=>item.classList.remove('active'));button.classList.add('active');activeGenre=button.dataset.genre;activeSearch='';currentPage=1;title.textContent=button.dataset.label;subtitle.textContent=`Une sélection ${button.dataset.genre.toLowerCase()} rien que pour toi.`;loadAnime();document.querySelector('#tendance').scrollIntoView({behavior:'smooth',block:'start'})});
document.querySelector('#searchButton').addEventListener('click',startSearch);
document.querySelector('#searchInput').addEventListener('keydown',event=>{if(event.key==='Enter')startSearch()});
grid.addEventListener('click',event=>{const card=event.target.closest('.anime-card');if(card)openAnime(card.dataset.id)});
grid.addEventListener('keydown',event=>{const card=event.target.closest('.anime-card');if(card&&event.key==='Enter')openAnime(card.dataset.id)});
document.querySelector('#closeDialog').addEventListener('click',()=>dialog.close());
dialogContent.addEventListener('click',event=>{const button=event.target.closest('[data-favorite]');if(button)toggleFavorite(button.dataset.favorite)});
moreButton.addEventListener('click',()=>browseMode==='season'?nextSeasonBatch():(currentPage++,loadAnime({append:true})));
document.querySelector('#seasonButton').addEventListener('click',()=>loadSeasonalAnime());
document.querySelector('#refreshSeasonButton').addEventListener('click',()=>browseMode==='season'?nextSeasonBatch():loadSeasonalAnime());
document.querySelector('#jikanButton').addEventListener('click',()=>{browseMode='explore';activeSearch='';activeGenre=null;title.textContent='Les incontournables MyAnimeList';loadJikan();document.querySelector('#tendance').scrollIntoView({behavior:'smooth'})});
document.querySelector('#favoritesButton').addEventListener('click',()=>{const ids=favorites();if(!ids.length){toast('Ta liste est encore vide.');return}const saved=currentItems.filter(item=>ids.includes(item.id));if(saved.length){browseMode='explore';title.textContent='Ma liste';subtitle.textContent='Les anime que tu veux regarder.';grid.innerHTML='';currentPage=1;renderCards(saved);moreButton.hidden=true;document.querySelector('#tendance').scrollIntoView({behavior:'smooth'})}else toast('Ouvre un anime récent pour voir ta liste.')});
async function withButton(button,task){button.disabled=true;const label=button.textContent;button.textContent='Chargement…';try{await task()}catch(error){toast('Ce service est indisponible pour le moment.')}finally{button.disabled=false;button.textContent=label}}
document.querySelector('#factButton').addEventListener('click',()=>withButton(document.querySelector('#factButton'),async()=>{const home=await fetch('https://anime-facts-rest-api.herokuapp.com/api/v1');if(!home.ok)throw Error();const catalog=await home.json(),all=catalog.data||[],pick=all[Math.floor(Math.random()*all.length)],response=await fetch(`https://anime-facts-rest-api.herokuapp.com/api/v1/${pick.anime_name}`);if(!response.ok)throw Error();const details=await response.json(),facts=details.data||[],fact=facts[Math.floor(Math.random()*facts.length)];if(!fact)throw Error();document.querySelector('#factText').textContent=fact.fact;document.querySelector('#factAuthor').textContent=`Anecdote : ${pick.anime_name.replaceAll('_',' ')}`}));
document.querySelector('#ghibliButton').addEventListener('click',()=>withButton(document.querySelector('#ghibliButton'),async()=>{const response=await fetch('https://ghibliapi.dev/films');if(!response.ok)throw Error();const films=await response.json(),film=films[Math.floor(Math.random()*films.length)];document.querySelector('#ghibliTitle').textContent=film.title;document.querySelector('#ghibliMeta').textContent=`${film.director} · ${film.release_date} · ${film.running_time} min · ${film.rt_score}/100`}));
document.querySelector('#traceUpload').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;const output=document.querySelector('#traceResult');output.hidden=false;output.textContent='Analyse de la capture en cours…';try{const response=await fetch('https://api.trace.moe/search?anilistInfo',{method:'POST',body:file});if(!response.ok)throw Error();const payload=await response.json(),match=payload.result?.[0];if(!match)throw Error();const minutes=Math.floor(match.from/60),seconds=Math.floor(match.from%60).toString().padStart(2,'0'),name=match.anilist?.title?.english||match.anilist?.title?.romaji||'Anime identifié';output.innerHTML=`<b>${escapeHtml(name)}</b>Épisode ${match.episode||'?'} · vers ${minutes}:${seconds} · correspondance ${Math.round(match.similarity*100)} %`}catch(error){output.textContent='Analyse indisponible. Essaie une capture nette provenant d’un épisode.'}});
updateFavoriteCount();
loadSeasonalAnime();
loadHeroCharacters();
